import{_ as s,C as n,o as i,c as d,ai as a,j as t,a as r,G as l}from"./chunks/framework.Ci0kozOl.js";const k=JSON.parse('{"title":"Release Notes","description":"","frontmatter":{},"headers":[],"relativePath":"3.0/prologue/release-notes.md","filePath":"3.0/prologue/release-notes.md","lastUpdated":1785947307000}'),c={name:"3.0/prologue/release-notes.md"},h={id:"unopim-v3-0-0",tabindex:"-1"};function p(u,e,m,g,f,b){const o=n("Badge");return i(),d("div",null,[e[3]||(e[3]=a('<h1 id="release-notes" tabindex="-1">Release Notes <a class="header-anchor" href="#release-notes" aria-label="Permalink to &quot;Release Notes&quot;">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>UnoPim 3.0 is a major release built on <strong>Laravel 13</strong> and <strong>PHP 8.4.1</strong>. It brings Digital Product Passports, configurable associations, advanced variants, a greatly expanded REST API, and a refreshed admin experience — alongside significant performance and security work.</p><p>Because this is a major version, it contains breaking changes. Before you upgrade a production installation, you should read the <a href="./upgrade-guide.html">Upgrade Guide</a> and run <code>php artisan unopim:upgrade --dry-run</code> to preview what the upgrade will do.</p><p>This page summarizes what shipped, from the headline features down to the breaking changes, with links to the detailed documentation for each area.</p>',5)),t("h2",h,[e[0]||(e[0]=r("UnoPim v3.0.0 ",-1)),l(o,{type:"tip",text:"July 31, 2026"}),e[1]||(e[1]=r()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#unopim-v3-0-0","aria-label":'Permalink to "UnoPim v3.0.0 <Badge type="tip" text="July 31, 2026" />"'},"​",-1))]),e[4]||(e[4]=a('<h3 id="headline-features" tabindex="-1">Headline Features <a class="header-anchor" href="#headline-features" aria-label="Permalink to &quot;Headline Features&quot;">​</a></h3><p>The table below lists the major new capabilities and where each is documented:</p><table tabindex="0"><thead><tr><th>Feature</th><th>Documentation</th></tr></thead><tbody><tr><td><strong>Digital Product Passports</strong> — templates, per-locale publishing, QR carriers, GS1 Digital Link, ESPR &amp; EU Battery Regulation presets</td><td><a href="./../advanced/digital-product-passport.html">Digital Product Passport</a></td></tr><tr><td><strong>Configurable Associations</strong> — custom association types with localized labels and per-link fields</td><td><a href="./../packages/configurable-associations.html">Configurable Associations</a></td></tr><tr><td><strong>Advanced Variants</strong> — two-level variant structures with read-time value inheritance</td><td><a href="./../packages/advanced-variants.html">Advanced Variants</a></td></tr><tr><td><strong>Measurements</strong> — measurement families, units, conversions, precision strategies</td><td><a href="./../packages/measurements.html">Measurements</a></td></tr><tr><td><strong>Multi-Webhooks</strong> — multiple endpoints, event subscriptions, HMAC delivery, logs</td><td><a href="./../packages/webhooks.html">Webhooks</a></td></tr><tr><td><strong>Microsoft SSO</strong> — Entra ID login with an extensible provider contract</td><td><a href="./../advanced/microsoft-sso.html">Microsoft SSO</a></td></tr><tr><td><strong>REST API expansion</strong> — full catalog CRUD, media, passports, delta sync</td><td><a href="./../api/whats-new-v3.html">What&#39;s New in the v3.0 API</a></td></tr></tbody></table><h3 id="admin-experience" tabindex="-1">Admin Experience <a class="header-anchor" href="#admin-experience" aria-label="Permalink to &quot;Admin Experience&quot;">​</a></h3><p>The admin panel now navigates SPA-style with AJAX and browser history, and a global unsaved-changes save bar protects your edits — see <a href="./../architecture/frontend.html">Frontend Architecture</a>. A dark theme is included, with automatic browser detection.</p><p>Working with the catalog is faster throughout: the product grid gains filters for category, completeness, dates, properties, and attribute values, plus saved grid views; catalog structures can be created from quick modals; a native category tree browser and lazy attribute-group loading keep large screens responsive; and products support quick export and asynchronous mass actions.</p><p>Configuration moved into a config-driven <a href="./../advanced/system-settings.html">System Settings hub</a> with package extension hooks, and each admin may now set a personal catalog locale and default channel.</p><h3 id="platform-developer" tabindex="-1">Platform &amp; Developer <a class="header-anchor" href="#platform-developer" aria-label="Permalink to &quot;Platform &amp; Developer&quot;">​</a></h3><p>The platform moves to Laravel 13, PHP 8.4.1, and Symfony 8 components, with Pest 5 / PHPUnit 13 for testing. Fresh Docker environments now default to native PostgreSQL support.</p><p>For extension authors, 3.0 opens several new surfaces: the <a href="./../packages/resource-crud-kit.html">Resource CRUD Kit</a>, the <code>SsoProvider</code> contract, variant resolver contracts, the publication <code>PayloadBuilder</code> / <code>PublicationGate</code> / type registry, and the webhook <code>EventRegistry</code>.</p><p>API integrations now run as robot users with a one-time credential reveal, and import/export jobs cover attributes, families, groups, options, category fields, associations, locales, channels, currencies, roles, and users.</p><h3 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h3><p>This release adds keyset pagination for large exports, hot-path indexes, queued mass actions, bounded Elasticsearch bulk indexing, and N+1 elimination across the family, variant, product, and user workflows — see <a href="./../advanced/performance-scalability.html">Performance &amp; Scalability</a>.</p><h3 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h3><p>OAuth signing keys are now per-installation 4096-bit keys, which invalidates existing tokens — clients must re-authenticate. The release also adds SSRF protection on webhooks and Magic AI, stored-XSS sanitisation, a centralized password policy, configurable CORS / rate limits / trusted hosts, and <code>APP_PREVIOUS_KEYS</code> rotation — see <a href="./../advanced/security-practice.html">Security Practices</a>.</p><h3 id="breaking-changes" tabindex="-1">Breaking Changes <a class="header-anchor" href="#breaking-changes" aria-label="Permalink to &quot;Breaking Changes&quot;">​</a></h3><p>The breaking changes are summarized in the <a href="./upgrade-guide.html#breaking-changes">Upgrade Guide</a>: the PHP/Laravel requirement bump, OAuth token invalidation, robot-user integration ownership, variant value storage, renamed admin URLs, the webhook module replacement, the Docker layout, the deprecated <code>configrable-products</code> alias, and removed classes.</p><p>For the exhaustive list of every change, see the <a href="https://github.com/unopim/unopim/blob/master/CHANGELOG.md" target="_blank" rel="noreferrer">CHANGELOG on GitHub</a>.</p>',18))])}const P=s(c,[["render",p]]);export{k as __pageData,P as default};
